const b = $json.body || $json;
const rawFrom = b.From || b.from || "";
const fromPlain = rawFrom.replace("whatsapp:", "");
const text = (b.Body || b.text || "").trim();
const numMedia = parseInt(b.NumMedia || b.numMedia || "0", 10) || 0;
const mediaContentType = b.MediaContentType0 || "";
const mediaUrl = b.MediaUrl0 || "";
const isVoice = numMedia > 0 && mediaContentType.indexOf("audio") === 0;
return { from: rawFrom, fromPlain: fromPlain, text: text, numMedia: numMedia, isVoice: isVoice, mediaUrl: mediaUrl, mediaContentType: mediaContentType, queryText: text };

const emb = ($json.embedding && $json.embedding.values) ? $json.embedding.values : [];
const literal = "[" + emb.join(",") + "]";
const raw = ($("Normalize Message").first().json.queryText || "").toLowerCase();
const q = raw.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
// Only [a-z0-9-] word tokens are ever placed into SQL.
const padded = " " + q.replace(/[^a-z0-9-]+/g, " ") + " ";
const hasWord = function (w) { return padded.indexOf(" " + w + " ") >= 0; };
const parts = ["(select id, title, content, source, source_type, verification_status, similarity from match_documents('" + literal + "'::vector, 5, 0.5))"];

// Safety: add official UK FCDO regional-risk advice when a high-risk area is mentioned.
const riskAreas = [
  { title: "North-West and South-West", words: ["north-west", "northwest", "north west", "nord-ouest", "nord ouest", "south-west", "southwest", "south west", "sud-ouest", "sud ouest", "bamenda", "nyos", "wum", "kumbo", "bafut", "ndop", "buea", "limbe", "kumba", "mamfe", "tiko", "korup", "mount cameroon", "mont cameroun"] },
  { title: "Far-North", words: ["far north", "far-north", "extreme-nord", "extreme nord", "maroua", "rhumsiki", "waza", "kousseri", "mokolo", "mora"] },
  { title: "Central African Republic border", words: ["garoua-boulai", "batouri", "central african", "centrafrique"] }
];
const advisories = [];
for (let i = 0; i < riskAreas.length; i++) {
  for (let w = 0; w < riskAreas[i].words.length; w++) {
    if (hasWord(riskAreas[i].words[w])) { advisories.push(riskAreas[i].title); break; }
  }
}
if (advisories.length) {
  const conds = [];
  for (let i = 0; i < advisories.length; i++) { conds.push("title like '%Regional risks%" + advisories[i] + "%'"); }
  parts.push("(select id, title, content, source, source_type, verification_status, 1.0::float as similarity from knowledge_documents where metadata->>'source_key' = 'fcdo' and (" + conds.join(" or ") + ") order by title, chunk_index limit 3)");
}

// Tariff Guard: add matching tariff rows when the message asks about prices.
const pricingWords = ["price", "prices", "prix", "cost", "costs", "cout", "coute", "fare", "fares", "tarif", "tarifs", "combien", "how much", "taxi", "moto", "ticket", "billet", "entree", "entry", "fee", "fees", "frais", "payer", "pay"];
let pricing = false;
for (let i = 0; i < pricingWords.length; i++) { if (hasWord(pricingWords[i])) { pricing = true; break; } }
if (pricing) {
  const stop = ["what", "much", "does", "from", "with", "that", "this", "there", "pour", "dans", "avec", "quel", "quelle", "quels", "combien", "price", "prices", "prix", "cost", "costs", "cout", "coute", "how", "the", "est", "une", "des", "les", "aux", "is", "are", "for", "per", "par", "fare", "fares", "tarif", "tarifs"];
  const words = padded.trim().split(" ");
  const keys = [];
  for (let i = 0; i < words.length && keys.length < 8; i++) {
    const w = words[i];
    if (w.length >= 4 && stop.indexOf(w) < 0 && keys.indexOf(w) < 0 && /^[a-z0-9-]+$/.test(w)) { keys.push(w); }
  }
  if (keys.length) {
    const hits = [];
    for (let i = 0; i < keys.length; i++) { hits.push("(search_text like '%" + keys[i] + "%')::int"); }
    parts.push("(select id, 'Tariff table' as title, 'Tariff: ' || description || coalesce('. Unit: ' || unit, '') || case when time_of_day <> 'any' then ' (' || time_of_day || ')' else '' end || coalesce('. Note: ' || notes, '') as content, source, 'tariff' as source_type, verification_status, 0.99::float as similarity from tariffs where search_text is not null and (" + hits.join(" + ") + ") > 0 order by (" + hits.join(" + ") + ") desc limit 3)");
  }
}
return { sqlQuery: parts.join(" union all "), embeddingLength: emb.length, advisories: advisories, pricing: pricing };

const rows = $input.all();
const nz = $("Normalize Message").first().json;
const labels = { verified: "VERIFIED", benchmark: "BENCHMARK", estimated: "ESTIMATED", unverified: "UNVERIFIED", unavailable: "UNAVAILABLE" };
const parts = [];
const seen = {};
let matchCount = 0;
for (let i = 0; i < rows.length; i++) {
  const j = rows[i].json || {};
  if (!j.content || (j.id && seen[j.id])) { continue; }
  if (j.id) { seen[j.id] = true; }
  matchCount++;
  const lab = labels[j.verification_status] || "UNVERIFIED";
  const title = j.title ? j.title : "Untitled";
  const src = j.source ? ("\nSource: " + j.source) : "";
  parts.push("[" + lab + "] " + title + "\n" + j.content + src);
}
const contextBlock = matchCount > 0 ? parts.join("\n\n---\n\n") : "(no verified information was retrieved for this query)";
const q = (nz.queryText || "").toLowerCase();
let language = "en";
if (q.indexOf("que ") >= 0 || q.indexOf("quoi") >= 0 || q.indexOf("combien") >= 0 || q.indexOf("bonjour") >= 0 || q.indexOf("voir") >= 0 || q.indexOf("prix") >= 0 || q.indexOf("merci") >= 0 || q.indexOf("pour ") >= 0) { language = "fr"; }
if (q.indexOf("wetin") >= 0 || q.indexOf("abeg") >= 0 || q.indexOf("na so") >= 0 || q.indexOf("comot") >= 0) { language = "pidgin"; }
const cities = ["limbe","kribi","douala","yaounde","foumban","buea","bamenda","bafoussam"];
let destination = "";
for (let c = 0; c < cities.length; c++) { if (q.indexOf(cities[c]) >= 0) { destination = cities[c]; break; } }
let queryCategory = "other";
if (q.indexOf("price") >= 0 || q.indexOf("prix") >= 0 || q.indexOf("cost") >= 0 || q.indexOf("fare") >= 0 || q.indexOf("combien") >= 0 || q.indexOf("tarif") >= 0) { queryCategory = "pricing"; }
else if (q.indexOf("hotel") >= 0 || q.indexOf("lodg") >= 0 || q.indexOf("accommod") >= 0 || q.indexOf("sleep") >= 0) { queryCategory = "hotels"; }
else if (q.indexOf("guide") >= 0) { queryCategory = "guides"; }
else if (q.indexOf("taxi") >= 0 || q.indexOf("moto") >= 0 || q.indexOf("bus") >= 0 || q.indexOf("transport") >= 0) { queryCategory = "transport"; }
else if (q.indexOf("emergency") >= 0 || q.indexOf("police") >= 0 || q.indexOf("hospital") >= 0 || q.indexOf("urgence") >= 0 || q.indexOf("secours") >= 0) { queryCategory = "emergency"; }
else if (q.indexOf("see") >= 0 || q.indexOf("visit") >= 0 || q.indexOf("attraction") >= 0 || q.indexOf("voir") >= 0 || q.indexOf("beach") >= 0 || q.indexOf("waterfall") >= 0 || q.indexOf("museum") >= 0 || q.indexOf("festival") >= 0) { queryCategory = "attractions"; }
const intent = queryCategory;
return [{ json: { contextBlock: contextBlock, matchCount: matchCount, queryText: nz.queryText, fromPlain: nz.fromPlain, rawMessage: nz.text, isVoice: nz.isVoice, language: language, destination: destination, intent: intent, queryCategory: queryCategory } }];

const sys = $json.systemPrompt;
const ctx = $json.contextBlock;
const q = $json.queryText;
const userPrompt = "VERIFIED INFORMATION (retrieved for this query):
" + ctx + "

USER MESSAGE:
" + q + "

Reply to the user following all the rules above, in the user's language.";
const geminiBody = { system_instruction: { parts: [ { text: sys } ] }, contents: [ { role: "user", parts: [ { text: userPrompt } ] } ], generation_config: { temperature: 0.3, max_output_tokens: 800, thinking_config: { thinking_budget: 0 } } };
return { geminiBody: geminiBody, queryText: q, fromPlain: $json.fromPlain, rawMessage: $json.rawMessage, language: $json.language, destination: $json.destination, intent: $json.intent, queryCategory: $json.queryCategory, isVoice: $json.isVoice };

const cands = $json.candidates || [];
let answer = "";
if (cands.length && cands[0].content && cands[0].content.parts) {
  for (let i = 0; i < cands[0].content.parts.length; i++) { answer += (cands[0].content.parts[i].text || ""); }
}
// WhatsApp formatting (mirrors rag/prompt.py format_for_whatsapp): **x** -> *x*, no # headings.
answer = answer.trim().replace(/\*\*([\s\S]+?)\*\*/g, "*$1*").replace(/^[ \t]{0,3}#{1,6}[ \t]*/gm, "").trim();
// Twilio rejects WhatsApp bodies over 1,600 characters: cap at 1,500 on a sentence boundary.
const LIMIT = 1500;
if (answer.length > LIMIT) {
  const cut = answer.slice(0, LIMIT);
  const end = Math.max(cut.lastIndexOf(". "), cut.lastIndexOf("! "), cut.lastIndexOf("? "), cut.lastIndexOf("\n"));
  answer = (end > LIMIT / 2 ? cut.slice(0, end + 1) : cut).trim() + " …";
}
const bg = $("Build Generation Request").first().json;
let status = "ok";
if (!answer) { answer = "I'm having trouble accessing that information right now. Please try again shortly."; status = "error"; }
let usedTariff = false;
const docs = $("Retrieve Documents").all();
for (let i = 0; i < docs.length; i++) { if (docs[i].json && docs[i].json.source_type === "tariff") { usedTariff = true; break; } }
return { answer: answer, fromPlain: bg.fromPlain, rawMessage: bg.rawMessage, normalizedMessage: bg.queryText, language: bg.language, destination: bg.destination, intent: bg.intent, queryCategory: bg.queryCategory, isVoice: bg.isVoice, responseStatus: status, toolUsed: usedTariff ? "tariff_guard" : "tourism_search", complaintFlag: false };

const ea = $("Extract Answer").first().json;
const tq = $("Log Tourist Query").first().json;
return { query_id: (tq && tq.id) ? tq.id : null, destination: ea.destination ? ea.destination : null, intent: ea.intent, language: ea.language, query_category: ea.queryCategory, tool_used: ea.toolUsed, response_status: ea.responseStatus, complaint_flag: ea.complaintFlag };
